import { dedent, write_if_changed } from './utils.js';

/**
 * @param {import('types').ManifestData} manifest_data
 * @param {string} output
 */
export function write_root(manifest_data, output) {
	// TODO remove default layout altogether

	const max_depth = Math.max(
		...manifest_data.routes.map((route) =>
			route.page ? route.page.layouts.filter(Boolean).length + 1 : 0
		),
		1
	);

	const levels = [];
	for (let i = 0; i <= max_depth; i += 1) {
		levels.push(i);
	}

	write_if_changed(
		`${output}/root.svelte`,
		dedent`
			<!-- This file is generated by @sveltejs/kit — do not edit it! -->
			<svelte:options runes={true} />
			<script>
				import { afterNavigate } from '$app/navigation';

				let { page, root, components = [], form, error } = $props();

				let mounted = $state(false);
				let navigated = $state(false);
				let title = $state(null);

				afterNavigate(() => {
					if (mounted) {
						navigated = true;
						title = document.title || 'untitled page';
					} else {
						mounted = true;
					}
				});
			</script>

			{#snippet node(n, depth)}
				<svelte:boundary>
					{#if n.child}
						<!-- svelte-ignore binding_property_non_reactive -->
						<n.component bind:this={components[depth]} data={n.data} {form} params={page.params}>
							{@render node(n.child, depth + 1)}
						</n.component>
					{:else}
						<!-- svelte-ignore binding_property_non_reactive -->
						<n.component bind:this={components[depth]} data={n.data} {form} params={page.params} {error} />
					{/if}

					{#snippet failed(error)}
						<n.error {error} />
					{/snippet}
				</svelte:boundary>
			{/snippet}

			{@render node(root, 0)}

			{#if mounted}
				<div id="svelte-announcer" aria-live="assertive" aria-atomic="true" style="position: absolute; left: 0; top: 0; clip: rect(0 0 0 0); clip-path: inset(50%); overflow: hidden; white-space: nowrap; width: 1px; height: 1px">
					{#if navigated}
						{title}
					{/if}
				</div>
			{/if}
		`
	);

	write_if_changed(
		`${output}/root.js`,
		dedent`
		import { asClassComponent } from 'svelte/legacy';
		import Root from './root.svelte';
		export default asClassComponent(Root);
	`
	);
}
